$intakeWalkScript = @'
import csv, hashlib, json
from collections import Counter
from pathlib import Path
p = Path('examples/real-penguins/data/penguins.csv')
with p.open(encoding='utf-8-sig', newline='') as f:
    rows = list(csv.DictReader(f))
fields = ('bill_length_mm', 'bill_depth_mm')
invalid = {field: [] for field in fields}
missing = {field: [] for field in fields}
for i, row in enumerate(rows, start=1):
    for field in fields:
        if row[field].strip() in {'', 'NA'}:
            missing[field].append(i)
        else:
            try:
                float(row[field])
            except ValueError:
                invalid[field].append(i)
print(json.dumps({'scope': 'local CSV structure and value-type checks only; no model or predictive statistics', 'sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'rows': len(rows), 'species_counts': dict(Counter(row['species'] for row in rows)), 'bill_missing_record_numbers_1_based': missing, 'nonmissing_non_numeric_record_numbers_1_based': invalid, 'deleted_rows': 0, 'model_runs': 0}, ensure_ascii=False, indent=2))
'@
$intakeWalkScript | py -3.12 -B -X utf8 -
exit $LASTEXITCODE

