$intakeArchiveInspect = @'
import hashlib, json
from pathlib import Path
repo = Path.cwd()
run = Path(r'<run>')
paths = [
'AGENTS.md', 'README.md', 'MODULE_INDEX.md', 'MODULES.json', 'docs/GETTING_STARTED.md', 'docs/RUNTIME_STATUS.md', 'prompts/README.md',
'workflows/automated-research/SKILL.md', 'workflows/automated-research/README.md', 'workflows/automated-research/START_HERE.md', 'workflows/automated-research/EXAMPLES.md', 'workflows/automated-research/skill-routing.json',
'modules/idea-discovery/SKILL_INDEX.md', 'modules/idea-discovery/04_KDense/upstream/skills/hypothesis-generation/SKILL.md',
'examples/real-penguins/data/README.md', 'examples/real-penguins/data/penguins.csv', 'scripts/start_research.py', 'scripts/research_pipeline.py'
]
fingerprints = {p: {'sha256': hashlib.sha256((repo / p).read_bytes()).hexdigest(), 'bytes': (repo / p).stat().st_size} for p in paths}
artifacts = []
snapshots = {}
for path in sorted(run.rglob('*')):
    if path.is_file():
        relative = path.relative_to(run).as_posix()
        artifacts.append({'path': '<run>/' + relative, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'bytes': path.stat().st_size})
        if path.suffix in {'.json', '.md', '.jsonl'}:
            raw = path.read_text(encoding='utf-8')
            if path.suffix == '.json':
                snapshots[relative] = json.loads(raw)
            elif path.suffix == '.jsonl':
                snapshots[relative] = [json.loads(line) for line in raw.splitlines() if line.strip()]
            else:
                snapshots[relative] = raw
print(json.dumps({'source_fingerprints': fingerprints, 'generated_files': artifacts, 'snapshots': snapshots}, ensure_ascii=False, indent=2))
'@
$intakeArchiveInspect | py -3.12 -B -X utf8 -
exit $LASTEXITCODE
